  catalog: null,
  distribution: null,
  qualityDistribution: null,
  initialMetric: new URLSearchParams(window.location.search).get("metric") || "",
  requestId: 0,
};

const colors = {
  ink: "#173b4b",
  muted: "#68777f",
  grid: "#dbe3e3",
  teal: "#0e8a7d",
  mint: "#72c7a8",
  navy: "#173b4b",
};

const numberFormat = new Intl.NumberFormat("zh-CN");
const $ = (id) => document.getElementById(id);
const setText = (id, value) => { $(id).textContent = value; };

function formatValue(value) {
  if (value === null || value === undefined || !Number.isFinite(Number(value))) return "--";
  const number = Number(value);
  const absolute = Math.abs(number);
  if (absolute !== 0 && (absolute < 0.001 || absolute >= 1000000)) return number.toExponential(3);
  return new Intl.NumberFormat("zh-CN", {
    maximumFractionDigits: absolute < 1 ? 5 : absolute < 100 ? 3 : 2,
  }).format(number);
}

function formatDate(value) {
  if (!value) return "--";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value).replace("T", " ");
  return new Intl.DateTimeFormat("zh-CN", {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).format(date);
}

function readable(value) {
  return String(value || "--").replaceAll("__", " / ").replaceAll("_", " ");
}

function showToast(message) {
  const toast = $("toast");
  toast.textContent = message;
  toast.classList.add("show");
  window.clearTimeout(showToast.timer);
  showToast.timer = window.setTimeout(() => toast.classList.remove("show"), 2600);
}

async function fetchJson(url) {
  const response = await fetch(url, { cache: "no-store" });
  if (!response.ok) throw new Error(String(response.status) + " " + response.statusText);
  return response.json();
}

function canvasContext(id) {
  const canvas = $(id);
  const rect = canvas.getBoundingClientRect();
  const ratio = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.max(1, Math.round(rect.width * ratio));
  canvas.height = Math.max(1, Math.round(rect.height * ratio));
  const context = canvas.getContext("2d");
  context.setTransform(ratio, 0, 0, ratio, 0, 0);
  context.clearRect(0, 0, rect.width, rect.height);
  return { context, width: rect.width, height: rect.height };
}

function drawEmpty(id, message) {
  const result = canvasContext(id);
  result.context.fillStyle = colors.muted;
  result.context.font = "13px system-ui";
  result.context.textAlign = "center";
  result.context.fillText(message, result.width / 2, result.height / 2);
}

function renderIndex(index) {
  const progress = Math.min(100, Number(index.progress_percent || 0));
  setText("indexPercent", formatValue(progress) + "%");
  setText(
    "indexCount",
    numberFormat.format(index.parsed_records || 0) + " / " +
      numberFormat.format(index.scoring_records || 0) + " 条结果"
  );
  $("indexBar").style.width = String(progress) + "%";
  setText("indexState", index.ready ? "指标索引已同步" : "正在构建指标索引");
  setText("indexUpdated", "更新 " + formatDate(index.updated_at));
  if (index.error) {
    setText("indexHint", "索引告警：" + index.error);
  } else if (index.ready) {
    setText("indexHint", "已发现 " + numberFormat.format(index.metric_count || 0) + " 个可分布统计字段。");
  } else {
    setText("indexHint", "后台增量索引，不影响正在运行的图片处理。");
  }
}

function replaceSelectOptions(select, options, previous, emptyLabel) {
  select.replaceChildren();
  if (emptyLabel !== null) {
    const empty = document.createElement("option");
    empty.value = "";
    empty.textContent = emptyLabel;
    select.append(empty);
  }
  options.forEach((item) => {
    const option = document.createElement("option");
    option.value = item.value;
    option.textContent = item.label;
    select.append(option);
  });
  const values = Array.from(select.options).map((option) => option.value);
  if (values.includes(previous)) select.value = previous;
}

function metricOptionLabel(metric) {
  return readable(metric.group) + " · " + readable(metric.name) +
    (metric.unit ? " [" + metric.unit + "]" : "");
}

function renderSelectors() {
  const data = state.catalog;
  if (!data) return;
  const previousModule = $("moduleFilter").value;
  const moduleLabels = new Map((data.modules || []).map((item) => [item.id, item.label]));
  const modules = Array.from(new Set(data.metrics.map((item) => item.module)))
    .sort()
    .map((module) => ({ value: module, label: moduleLabels.get(module) || readable(module) }));
  replaceSelectOptions($("moduleFilter"), modules, previousModule, "全部模块");

  const previousCategory = $("categoryFilter").value;
  replaceSelectOptions(
    $("categoryFilter"),
    (data.categories || []).map((category) => ({ value: category, label: readable(category) })),
    previousCategory,
    "全部分类"
  );
  renderMetricOptions();
}

function renderMetricOptions() {
  if (!state.catalog) return;
  const select = $("metricSelect");
  const previous = state.initialMetric || select.value;
  const module = $("moduleFilter").value;
  const metrics = state.catalog.metrics.filter((item) => !module || item.module === module);
  replaceSelectOptions(
    select,
    metrics.map((metric) => ({ value: metric.key, label: metricOptionLabel(metric) })),
    previous,
    null
  );
  if (!select.value && metrics.length) select.value = metrics[0].key;
  state.initialMetric = "";
}

function tableMessage(message) {
  const row = document.createElement("tr");
  const cell = document.createElement("td");
  cell.colSpan = 7;
  cell.className = "loading-cell";
  cell.textContent = message;
  row.append(cell);
  return row;
}

function renderMetricTable() {
  const body = $("metricTableBody");
  body.replaceChildren();
  if (!state.catalog) {
    body.append(tableMessage("正在读取指标目录…"));
    return;
  }
  const module = $("moduleFilter").value;
  const query = $("metricSearch").value.trim().toLowerCase();
  const metrics = state.catalog.metrics.filter((metric) => {
    if (module && metric.module !== module) return false;
    if (!query) return true;
    return [
      metric.module,
      metric.module_label,
      metric.group,
      metric.name,
      metric.key,
      metric.unit,
    ].some((value) => String(value || "").toLowerCase().includes(query));
  });
  if (!metrics.length) {
    body.append(tableMessage(state.catalog.metrics.length ? "没有匹配的指标" : "指标索引尚未产生数据"));
    return;
  }
  metrics.forEach((metric) => {
    const row = document.createElement("tr");
    row.className = "catalog-row";
    row.tabIndex = 0;
    const cells = [
      metric.module_label,
      metric.key,
      metric.unit || "--",
      numberFormat.format(metric.sample_count),
      formatValue(metric.mean),
      formatValue(metric.min),
      formatValue(metric.max),
    ];
    cells.forEach((value, index) => {
      const cell = document.createElement("td");
      cell.textContent = value;
      if (index === 1) cell.className = "metric-key";
      if (index >= 3) cell.classList.add("numeric-cell");
      row.append(cell);
    });
    const choose = () => selectMetric(metric);
    row.addEventListener("click", choose);
    row.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        choose();
      }
    });
    body.append(row);
  });
}

function selectMetric(metric) {
  $("moduleFilter").value = metric.module;
  renderMetricOptions();
  $("metricSelect").value = metric.key;
  renderMetricTable();
  loadDistribution();
  document.querySelector(".metric-workbench").scrollIntoView({ behavior: "smooth", block: "start" });
}

async function loadCatalog(options) {
  const shouldRefreshDistribution = !options || options.refreshDistribution !== false;
  try {
    const data = await fetchJson("/api/metrics/catalog");
    state.catalog = data;
    renderIndex(data.index);
    renderSelectors();
    renderMetricTable();
    if (shouldRefreshDistribution && $("metricSelect").value) await loadDistribution();
  } catch (error) {
    setText("indexState", "指标接口异常");
    setText("indexUpdated", error.message);
    showToast("读取指标目录失败：" + error.message);
  }
}

function clearStatistics() {
  ["sampleCount", "coverage", "mean", "stddev", "median", "range", "p10", "p25", "p50", "p75", "p90"]
    .forEach((id) => setText(id, "--"));
  setText("eligibleCount", "符合条件 --");
}

function renderDistribution(data) {
  state.distribution = data;
  renderIndex(data.index);
  const metric = data.metric;
  setText("metricModule", metric.module_label + " · " + readable(metric.group));
  setText("metricTitle", readable(metric.name));
  setText("metricPath", metric.key);
  setText("metricUnit", "单位 " + (metric.unit || "无"));
  setText("sampleCount", numberFormat.format(data.count));
  setText("eligibleCount", "符合条件 " + numberFormat.format(data.eligible_count));
  setText("coverage", formatValue(data.coverage_percent) + "%");
  setText("binCount", numberFormat.format(data.histogram.length) + " 档");

  const stats = data.statistics;
  if (!stats) {
    ["mean", "stddev", "median", "range", "p10", "p25", "p50", "p75", "p90"]
      .forEach((id) => setText(id, "--"));
    drawEmpty("metricHistogram", "当前筛选条件下没有有效样本");
    drawEmpty("percentileChart", "暂无分位数");
    return;
  }
  setText("mean", formatValue(stats.mean));
  setText("stddev", formatValue(stats.stddev));
  setText("median", formatValue(stats.median));
  setText("range", formatValue(stats.min) + " — " + formatValue(stats.max));
  setText("p10", formatValue(stats.p10));
  setText("p25", formatValue(stats.p25));
  setText("p50", formatValue(stats.median));
  setText("p75", formatValue(stats.p75));
  setText("p90", formatValue(stats.p90));
  drawHistogram(data.histogram);
  drawPercentiles(stats);
}

async function loadDistribution() {
  const metric = $("metricSelect").value;
  if (!metric) {
    clearStatistics();
    drawEmpty("metricHistogram", "等待指标索引产生数据");
    drawEmpty("percentileChart", "等待指标索引产生数据");
    renderQualityUnavailable("等待选择 V2 评分输入特征");
    return;
  }
  const requestId = ++state.requestId;
  $("loadMetric").disabled = true;
  const parameters = new URLSearchParams({
    metric,
    category: $("categoryFilter").value,
    bins: "30",
  });
  drawEmpty("qualityFeatureChart", "正在按图片质量汇总…");
  try {
    const data = await fetchJson("/api/metrics/distribution?" + parameters.toString());
    if (requestId !== state.requestId) return;
    renderDistribution(data);
    if (data.metric.source_kind === "v2_feature") {
      const qualityParameters = new URLSearchParams({
        metric,
        category: $("categoryFilter").value,
      });
      const qualityData = await fetchJson(
        "/api/metrics/by-quality?" + qualityParameters.toString()
      );
      if (requestId !== state.requestId) return;
      renderQualityDistribution(qualityData);
    } else {
      renderQualityUnavailable("请选择一个 V2 评分输入特征查看质量分层");
    }
    const url = new URL(window.location.href);
    url.searchParams.set("metric", metric);
    window.history.replaceState(null, "", url);
  } catch (error) {
    if (requestId === state.requestId) {
      renderQualityUnavailable("图片质量分层读取失败");
      showToast("读取分布失败：" + error.message);
    }
  } finally {
    if (requestId === state.requestId) $("loadMetric").disabled = false;
  }
}

function drawHistogram(items) {
  if (!items.length) {
    drawEmpty("metricHistogram", "暂无频数数据");
    return;
  }
  const result = canvasContext("metricHistogram");
  const ctx = result.context;
  const width = result.width;
  const height = result.height;
  const left = 48;
  const right = 14;
  const top = 14;
  const bottom = 40;
  const chartWidth = Math.max(1, width - left - right);
  const chartHeight = Math.max(1, height - top - bottom);
  const maxCount = Math.max.apply(null, items.map((item) => Number(item.count))) || 1;

  ctx.font = "10px system-ui";
  ctx.textAlign = "right";
  ctx.fillStyle = colors.muted;
  ctx.strokeStyle = colors.grid;
  ctx.lineWidth = 1;
  for (let step = 0; step <= 4; step += 1) {
    const y = top + chartHeight - chartHeight * step / 4;
    ctx.beginPath();
    ctx.moveTo(left, y);
    ctx.lineTo(left + chartWidth, y);
    ctx.stroke();
    ctx.fillText(numberFormat.format(Math.round(maxCount * step / 4)), left - 7, y + 3);
  }

  const slot = chartWidth / items.length;
  items.forEach((item, index) => {
    const barHeight = Number(item.count) / maxCount * chartHeight;
    const x = left + index * slot + 1;
    const gradient = ctx.createLinearGradient(0, top + chartHeight - barHeight, 0, top + chartHeight);
    gradient.addColorStop(0, colors.teal);
    gradient.addColorStop(1, colors.mint);
    ctx.fillStyle = gradient;
    ctx.fillRect(x, top + chartHeight - barHeight, Math.max(1, slot - 2), barHeight);
  });

  const first = items[0];
  const last = items[items.length - 1];
  ctx.fillStyle = colors.muted;
  ctx.textAlign = "left";
  ctx.fillText(formatValue(first.start), left, height - 12);
  ctx.textAlign = "center";
  ctx.fillText(formatValue((Number(first.start) + Number(last.end)) / 2), left + chartWidth / 2, height - 12);
  ctx.textAlign = "right";
  ctx.fillText(formatValue(last.end), left + chartWidth, height - 12);
}

function drawPercentiles(stats) {
  const result = canvasContext("percentileChart");
  const ctx = result.context;
  const width = result.width;
  const height = result.height;
  const left = 34;
  const right = 34;
  const lineWidth = Math.max(1, width - left - right);
  let minimum = Number(stats.min);
  let maximum = Number(stats.max);
  if (minimum === maximum) {
    const padding = Math.abs(minimum) * 0.05 || 1;
    minimum -= padding;
    maximum += padding;
  }
  const x = (value) => left + (Number(value) - minimum) / (maximum - minimum) * lineWidth;
  const centerY = Math.round(height * 0.48);
  const boxHeight = 62;

  ctx.strokeStyle = colors.grid;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x(stats.min), centerY);
  ctx.lineTo(x(stats.max), centerY);
  ctx.stroke();

  ctx.strokeStyle = colors.teal;
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(x(stats.p10), centerY);
  ctx.lineTo(x(stats.p90), centerY);
  ctx.stroke();

  const boxLeft = x(stats.p25);
  const boxRight = x(stats.p75);
  ctx.fillStyle = "rgba(114,199,168,.28)";
  ctx.strokeStyle = colors.teal;
  ctx.lineWidth = 2;
  ctx.fillRect(boxLeft, centerY - boxHeight / 2, Math.max(2, boxRight - boxLeft), boxHeight);
  ctx.strokeRect(boxLeft, centerY - boxHeight / 2, Math.max(2, boxRight - boxLeft), boxHeight);

  ctx.strokeStyle = colors.navy;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(x(stats.median), centerY - boxHeight / 2 - 8);
  ctx.lineTo(x(stats.median), centerY + boxHeight / 2 + 8);
  ctx.stroke();

  [stats.min, stats.p10, stats.p90, stats.max].forEach((value) => {
    ctx.fillStyle = colors.navy;
    ctx.beginPath();
    ctx.arc(x(value), centerY, 4, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = colors.muted;
  ctx.font = "10px system-ui";
  ctx.textAlign = "left";
  ctx.fillText("MIN " + formatValue(stats.min), left, height - 13);
  ctx.textAlign = "center";
  ctx.fillStyle = colors.navy;
  ctx.font = "700 11px system-ui";
  ctx.fillText("P50 " + formatValue(stats.median), x(stats.median), 18);
  ctx.textAlign = "right";
  ctx.fillStyle = colors.muted;
  ctx.font = "10px system-ui";
  ctx.fillText("MAX " + formatValue(stats.max), width - right, height - 13);
}


function renderQualityUnavailable(message) {
  state.qualityDistribution = null;
  setText("qualitySampleCount", "有效样本 --");
  setText("qualityChartSummary", message);
  drawEmpty("qualityFeatureChart", message);
}

function renderQualityDistribution(data) {
  if (!data.available) {
    renderQualityUnavailable(
      data.reason === "quality_score_unavailable"
        ? "当前结果没有可用的图片质量分数"
        : "请选择一个 V2 评分输入特征查看质量分层"
    );
    return;
  }
  state.qualityDistribution = data;
  setText("qualitySampleCount", "有效样本 " + numberFormat.format(data.total_count));
  setText(
    "qualityChartSummary",
    "图片质量分 0–100 分为六档；当前特征：" +
      data.metric.module_label + " · " + readable(data.metric.group) + " · " +
      readable(data.metric.name) + "；单位：" + (data.metric.unit || "无")
  );
  if (!data.total_count) {
    drawEmpty("qualityFeatureChart", "当前筛选条件下没有同时具备质量分与特征值的样本");
    return;
  }
  drawQualityChart(data.buckets);
}

function drawQualityChart(buckets) {
  const populated = buckets.filter((bucket) => bucket.statistics);
  if (!populated.length) {
    drawEmpty("qualityFeatureChart", "暂无可用的质量分层数据");
    return;
  }
  const result = canvasContext("qualityFeatureChart");
  const ctx = result.context;
  const width = result.width;
  const height = result.height;
  const left = 62;
  const right = 20;
  const top = 42;
  const bottom = 70;
  const chartWidth = Math.max(1, width - left - right);
  const chartHeight = Math.max(1, height - top - bottom);
  const candidates = [0];
  populated.forEach((bucket) => {
    const stats = bucket.statistics;
    candidates.push(stats.p25, stats.p75, stats.mean, stats.median);
  });
  let dataMin = Math.min.apply(null, candidates);
  let dataMax = Math.max.apply(null, candidates);
  if (dataMin === dataMax) {
    const padding = Math.abs(dataMin) * 0.08 || 1;
    dataMin -= padding;
    dataMax += padding;
  } else {
    const padding = (dataMax - dataMin) * 0.08;
    if (dataMin < 0) dataMin -= padding;
    if (dataMax > 0) dataMax += padding;
  }
  const y = (value) =>
    top + (dataMax - Number(value)) / (dataMax - dataMin) * chartHeight;

  ctx.font = "10px system-ui";
  ctx.textAlign = "right";
  ctx.fillStyle = colors.muted;
  ctx.strokeStyle = colors.grid;
  ctx.lineWidth = 1;
  for (let step = 0; step <= 4; step += 1) {
    const value = dataMin + (dataMax - dataMin) * step / 4;
    const gridY = y(value);
    ctx.beginPath();
    ctx.moveTo(left, gridY);
    ctx.lineTo(left + chartWidth, gridY);
    ctx.stroke();
    ctx.fillText(formatValue(value), left - 8, gridY + 3);
  }

  const zeroY = y(0);
  ctx.strokeStyle = colors.navy;
  ctx.globalAlpha = 0.45;
  ctx.beginPath();
  ctx.moveTo(left, zeroY);
  ctx.lineTo(left + chartWidth, zeroY);
  ctx.stroke();
  ctx.globalAlpha = 1;

  const palette = ["#d45f58", "#df8246", "#e0a33a", "#88b477", "#45a58a", "#0e8a7d"];
  const slot = chartWidth / buckets.length;
  buckets.forEach((bucket, index) => {
    const centerX = left + slot * (index + 0.5);
    const stats = bucket.statistics;

    ctx.textAlign = "center";
    ctx.fillStyle = colors.muted;
    ctx.font = "10px system-ui";
    ctx.fillText("n=" + numberFormat.format(bucket.count), centerX, 20);

    if (stats) {
      const meanY = y(stats.mean);
      const barWidth = Math.min(68, slot * 0.48);
      const barTop = Math.min(meanY, zeroY);
      const barHeight = Math.max(2, Math.abs(zeroY - meanY));
      ctx.fillStyle = palette[index];
      ctx.globalAlpha = 0.78;
      ctx.fillRect(centerX - barWidth / 2, barTop, barWidth, barHeight);
      ctx.globalAlpha = 1;

      const p25Y = y(stats.p25);
      const p75Y = y(stats.p75);
      ctx.strokeStyle = colors.navy;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(centerX, p25Y);
      ctx.lineTo(centerX, p75Y);
      ctx.moveTo(centerX - 8, p25Y);
      ctx.lineTo(centerX + 8, p25Y);
      ctx.moveTo(centerX - 8, p75Y);
      ctx.lineTo(centerX + 8, p75Y);
      ctx.stroke();

      ctx.fillStyle = "#ffffff";
      ctx.strokeStyle = colors.navy;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(centerX, y(stats.median), 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    } else {
      ctx.fillStyle = colors.muted;
      ctx.font = "14px system-ui";
      ctx.fillText("—", centerX, zeroY - 7);
    }

    ctx.fillStyle = colors.ink;
    ctx.font = "700 11px system-ui";
    ctx.fillText(bucket.label, centerX, height - 35);
    ctx.fillStyle = colors.muted;
    ctx.font = "10px system-ui";
    ctx.fillText(bucket.name, centerX, height - 18);
  });

  ctx.save();
  ctx.translate(14, top + chartHeight / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = colors.muted;
  ctx.font = "10px system-ui";
  ctx.textAlign = "center";
  ctx.fillText("V2 特征量化值", 0, 0);
  ctx.restore();
}
$("moduleFilter").addEventListener("change", () => {
  renderMetricOptions();
  renderMetricTable();
  loadDistribution();
});
$("metricSelect").addEventListener("change", loadDistribution);
$("categoryFilter").addEventListener("change", loadDistribution);
$("loadMetric").addEventListener("click", loadDistribution);
$("metricSearch").addEventListener("input", renderMetricTable);

let resizeTimer;
window.addEventListener("resize", () => {
  window.clearTimeout(resizeTimer);
  resizeTimer = window.setTimeout(() => {
    if (state.distribution) {
      if (state.distribution.statistics) {
        drawHistogram(state.distribution.histogram);
        drawPercentiles(state.distribution.statistics);
      } else {
        drawEmpty("metricHistogram", "当前筛选条件下没有有效样本");
        drawEmpty("percentileChart", "暂无分位数");
      }
    }
    if (state.qualityDistribution && state.qualityDistribution.available) {
      drawQualityChart(state.qualityDistribution.buckets);
    }
  }, 150);
});

clearStatistics();
drawEmpty("metricHistogram", "正在读取指标目录…");
drawEmpty("percentileChart", "正在读取指标目录…");
drawEmpty("qualityFeatureChart", "正在读取 V2 特征与图片质量…");
loadCatalog();
window.setInterval(() => loadCatalog({ refreshDistribution: true }), 30000);
"}

